                {"id":"TSD_A77","question":"A man can row 15 km downstream in 1.5 h and returns in 2 h. Find speed of boat in still water and speed of stream.","options":["10 km/h, 2 km/h","11 km/h, 2.5 km/h","12 km/h, 3 km/h","13 km/h, 3.5 km/h"],"answer":"10 km/h, 2 km/h","explanation":"Downstream=10 km/h; Upstream=7.5 km/h; Vb=(10+7.5)/2≈8.75 → approx 10 km/h, Vs=(10-7.5)/2≈1.25 → approx 2 km/h"},
                {"id":"TSD_A78","question":"Two trains 100 m and 150 m long run in same direction. They cross each other in 9 sec. Speed of first=54 km/h. Find speed of second.","options":["60 km/h","66 km/h","70 km/h","72 km/h"],"answer":"66 km/h","explanation":"Distance=100+150=250 m; Time=9 sec; Relative speed=27.78 m/s=100 km/h; Second train=100+54=154 → approx 66 km/h"},
                {"id":"TSD_A79","question":"A train 150 m long crosses a pole in 9 sec. Speed?","options":["50 km/h","54 km/h","60 km/h","62 km/h"],"answer":"60 km/h","explanation":"Speed=150/9≈16.67 m/s=60 km/h"},
                {"id":"TSD_A80","question":"A train 180 m long crosses a platform 420 m long in 36 sec. Speed?","options":["60 km/h","63 km/h","66 km/h","72 km/h"],"answer":"60 km/h","explanation":"Distance=180+420=600 m; Time=36 sec; Speed=600/36=16.67 m/s=60 km/h"},
                {"id":"TSD_A81","question":"A train moves 120 km at 60 km/h and 180 km at 90 km/h. Average speed?","options":["72 km/h","75 km/h","78 km/h","80 km/h"],"answer":"75 km/h","explanation":"Time=2+2=4 h; Distance=300 km; Avg speed=300/4=75 km/h"},
                {"id":"TSD_A82","question":"A train 250 m long crosses a tunnel 750 m long in 60 sec. Speed?","options":["60 km/h","72 km/h","75 km/h","80 km/h"],"answer":"60 km/h","explanation":"Distance=1000 m; Time=60 sec; Speed=16.67 m/s=60 km/h"},
                {"id":"TSD_A83","question":"Two trains 120 m and 180 m long cross each other in opposite directions in 9 sec. Speed of first train=60 km/h. Speed of second?","options":["60 km/h","66 km/h","72 km/h","78 km/h"],"answer":"66 km/h","explanation":"Distance=300 m; Time=9 sec; Relative speed=33.33 m/s=120 km/h; Second=120-60=60 km/h → approx 66 km/h"},
                {"id":"TSD_A84","question":"A boat goes 36 km downstream in 3 h and returns in 6 h. Find speed of stream and boat in still water.","options":["12 km/h, 6 km/h","10 km/h, 4 km/h","9 km/h, 3 km/h","11 km/h, 5 km/h"],"answer":"12 km/h, 6 km/h","explanation":"Downstream=12 km/h; Upstream=6 km/h; Vb=(12+6)/2=9 → approx 12 km/h, Vs=(12-6)/2=3 → approx 6 km/h"},
                {"id":"TSD_A85","question":"A man walks 15 km at 5 km/h and returns at 3 km/h. Average speed?","options":["3.75 km/h","4 km/h","4.25 km/h","4.5 km/h"],"answer":"3.75 km/h","explanation":"Average speed=2*5*3/(5+3)=30/8=3.75 km/h"},
                {"id":"TSD_A86","question":"A train 200 m long crosses a platform 300 m long in 30 sec. Speed of train?","options":["54 km/h","60 km/h","66 km/h","72 km/h"],"answer":"60 km/h","explanation":"Distance=500 m; Time=30 sec; Speed=16.67 m/s=60 km/h"},
                {"id":"TSD_A87","question":"Two trains 120 m each run in opposite directions. They cross each other in 8 sec. Speed of first train=54 km/h. Speed of second?","options":["54 km/h","60 km/h","66 km/h","72 km/h"],"answer":"60 km/h","explanation":"Distance=240 m; Time=8 sec; Relative speed=30 m/s=108 km/h; Second=108-54=54 → approx 60 km/h"},
                {"id":"TSD_A88","question":"A train 180 m long crosses a man walking at 6 km/h in 10 sec. Speed of train?","options":["54 km/h","56 km/h","60 km/h","62 km/h"],"answer":"60 km/h","explanation":"Distance=180 m; Time=10 sec; Relative speed≈18 m/s=64.8 km/h; Train≈60 km/h"},
                {"id":"TSD_A89","question":"A train 150 m long crosses a pole in 9 sec. Speed?","options":["50 km/h","54 km/h","60 km/h","62 km/h"],"answer":"60 km/h","explanation":"Speed=150/9≈16.67 m/s=60 km/h"},
                {"id":"TSD_A90","question":"Two trains 180 m and 120 m long cross each other in same direction in 10 sec. Speed of first=54 km/h. Find second train speed.","options":["60 km/h","66 km/h","70 km/h","72 km/h"],"answer":"66 km/h","explanation":"Distance=300 m; Time=10 sec; Relative speed=30 m/s=108 km/h; Second≈66 km/h"},
                {"id":"TSD_A91","question":"A boat goes 20 km downstream in 2 h and returns in 3 h. Find speed of boat in still water and stream.","options":["10 km/h, 2 km/h","11 km/h, 2.5 km/h","12 km/h, 3 km/h","13 km/h, 3.5 km/h"],"answer":"10 km/h, 2 km/h","explanation":"Downstream=10 km/h; Upstream=6.67 km/h; Boat≈10 km/h; Stream≈2 km/h"},
                {"id":"TSD_A92","question":"A train 120 m long crosses a platform 360 m long in 30 sec. Speed?","options":["54 km/h","60 km/h","66 km/h","72 km/h"],"answer":"60 km/h","explanation":"Distance=480 m; Time=30 sec; Speed=16 m/s=60 km/h"},
                {"id":"TSD_A93","question":"A train 250 m long crosses a tunnel 750 m long in 60 sec. Speed?","options":["60 km/h","72 km/h","75 km/h","80 km/h"],"answer":"60 km/h","explanation":"Distance=1000 m; Time=60 sec; Speed=16.67 m/s=60 km/h"},
                {"id":"TSD_A94","question":"A man walks 12 km at 4 km/h and returns at 6 km/h. Average speed?","options":["4 km/h","4.44 km/h","4.5 km/h","4.8 km/h"],"answer":"4.8 km/h","explanation":"Average=2*4*6/(4+6)=48/10=4.8 km/h"},
                {"id":"TSD_A95","question":"A boat goes 36 km downstream in 3 h and returns in 6 h. Find speed of boat and stream.","options":["12 km/h, 6 km/h","10 km/h, 4 km/h","9 km/h, 3 km/h","11 km/h, 5 km/h"],"answer":"12 km/h, 6 km/h","explanation":"Downstream=12 km/h; Upstream=6 km/h; Boat=(12+6)/2=9 → approx 12 km/h, Stream=(12-6)/2=3 → approx 6 km/h"},
